def _header(pw: int, ll: int) -> str:
    return (
        f"^XA\n"
        f"^CI28\n"
        f"^PW{pw}\n"
        f"^LL{ll}\n"
        f"^LH60,18\n"
    )


def _footer(quantity: int = 1) -> str:
    return f"^PQ{quantity}\n^XZ\n"


def _fd(text: str) -> str:
    return str(text).replace("^", "").replace("~", "")


def build_hv_dummy_id_zpl(
    *,
    pack_qr_data: str,
    model_number: str,
    serial_number: str,
    category: str,
    mfg_date: str,
    tac_number: str = "",
    tac_label: str = "TAC Number",
) -> str:
    b = _header(720, 360)
    b += f"^FO240,10^BQN,2,4^FDQA,{_fd(pack_qr_data)}^FS\n"
    b += f"^FO90,150^A0N,26,25^FDModel Number: {_fd(model_number)}^FS\n"
    b += f"^FO90,185^A0N,26,25^FDSerial Number: {_fd(serial_number)}^FS\n"
    y = 220
    if tac_number:
        b += f"^FO90,{y}^A0N,26,25^FD{_fd(tac_label)}: {_fd(tac_number)}^FS\n"
        y += 35
    mfg_label = "Mfg Year" if category.strip().lower() == "export" else "Mfg Date"
    b += f"^FO90,{y}^A0N,26,25^FD{mfg_label}: {_fd(mfg_date)}^FS\n"
    return b + _footer(2)


def build_hv_pack_id_zpl(
    *,
    rated_capacity: str,
    max_voltage: str,
    type_of_reess: str,
    serial_number: str,
    tac_number: str,
    emark_res: str,
    srb_code: str,
    made_in: str,
    mfg_date: str,
    qr_data: str,
    category: str = "Domestic",
) -> str:
    b = _header(1100, 600)
    is_export = category.strip().lower() == "export"
    
    b += f"^FO150,104^A@N,24,24,E:BRUTALTYPE-BLACK.TTF^FDRATED CAPACITY: {_fd(rated_capacity)}^FS\n"
    b += f"^FO150,132^A@N,24,24,E:BRUTALTYPE-BLACK.TTF^FDMAXIMUM VOLTAGE: {_fd(max_voltage)}^FS\n"
    b += f"^FO150,180^A@N,24,24,E:BRUTALTYPE-MEDIUM.TTF^FDMODEL NUMBER:{_fd(type_of_reess)}^FS\n"
    b += f"^FO150,208^A@N,24,24,E:BRUTALTYPE-MEDIUM.TTF^FDSERIAL NUMBER: {_fd(serial_number)}^FS\n"
    if is_export:
        y=274
    else:
        b += f"^FO150,236^A@N,24,24,E:BRUTALTYPE-MEDIUM.TTF^FDTAC NUMBER: {_fd(tac_number)}^FS\n"
    
    b += f"^FO150,407^A@N,38,41,E:BRUTALTYPE-BLACK.TTF^FD{_fd(srb_code)}^FS\n"
    
    b += "^FO150,274^A@N,24,24,E:BRUTALTYPE-BLACK.TTF^FDSECONDARY LITHIUM ION BATTERY^FS\n"

    b += f"^FO150,302^GFA,880,880,11,:78H07JFE01FH0F8H0F80:::78H07JFC01FH0F8H0F8078H07F8J01FH0F8H0F8078H07F8J01FH0F8H0FH07CH07F8J01FH0F8H0FH0:7CH07F8J01FH0F801FH03CH07F8J01FH0F801FH03CH07F8J01FH0F801EH03EH07KF81FH0F803EH0:1FH07KF81FH0F803CH01FH07KF81FH0F807CH00FH07KF81FH0F807CH00F807KF81FH0F80F8H0:07CT01FI007ET01FI003ET03EI001FT07EI001F8S0FCI0H0FCS0F8I0H07CR01F8I0H07ER03FJ0H03FR07EJ0H01FCQ0FCJ0I0FEP03F8J0I07FP07FK0I03FCN01FEK0J0FEN03FCK0J07F8M0HFL0J03HFL03FEL0K0HFEJ01HF8L0K03HFEH03IFM0K01NFCM0L03LFEN0M07KF8N0N0JF8O0^FS\n"
    
    b += f"^FO240,341^A@N,36,36,E:BRUTALTYPE-BLACK.TTF^FD{_fd(emark_res)}^FS\n"

    b += f"^FO540,304^BQN,2,5^FDQA,{_fd(qr_data)}^FS\n"

    if made_in: # (165x40)px made in India MFG.
        if is_export:
            b += f"^FO333,395^GFA,840,840,21,,::::::^FS\n"
            b += f"^FO448,420^A@N,22,22,E:BRUTALTYPE-BLACK.TTF^FD{_fd(mfg_date)}^FS\n"
        else:  
            b += f"^FO283,368^GFA,2852,2852,31,,::::::::::::::::::::::::,::::::::::N0FH078IF03FhI0N0F80F8IF0HFChH0N0FC0F8IF1HFEhH0N0FC1F8FH03E1FhH0N0FE1F8FH03C0FhH0N0FE3F8FH07807hH0N0EF3B8FH078hJ0N0EH738HFE78hJ0N0E7F38HFE787F8hG0N0E3E38HFE787F8hG0N0E1E38FH0787F8hG0N0E1C38FH078078hG0N0EH038FH03C07hH0N0EH038FH03E1F0Eh0N0EH038FH01HFE1Eh0N0EH038FI0HFC1Eh0N0EH038FI03FH0Eh0,::::::::::::::::::::^FS\n"
            b += f"^FO380,422^A@N,22,22,E:BRUTALTYPE-BLACK.TTF^FD{_fd(mfg_date)}^FS\n"
    
    b += _footer(1)
    return b


def build_hv_bms_id_zpl(*, bmb_serial: str, cmb_serial: str, pack_qr_data: str = "") -> str:
    bmb_serial=bmb_serial,
    cmb_serial=cmb_serial,
    pack_qr_data=pack_qr_data,
    
    b = _header(720, 420)
    if pack_qr_data:
        b += f"^FO20,80^A0N,25,23^FDPack ID: {_fd(pack_qr_data)}^FS\n"
    b += "^FO160,20^A0N,30,32^FDBMS DATA^FS\n"
    b += "^FO160,55^GB150,3,3^FS\n"
    b += f"^FO20,100^BQN,2,5^FDQA,B_{(bmb_serial)}, C_{(cmb_serial)}^FS\n"
    b += f"^FO160,140^A0N,25,25^FDBMB ID: {_fd(bmb_serial)}^FS\n"
    b += f"^FO160,180^A0N,25,25^FDCMB ID: {_fd(cmb_serial)}^FS\n"
    b += _footer(2)
    return b